// קובץ מעקב בלי שורה להיום (26.10.26): המתאמן/ת מקבל/ת הודעה ברורה, ולאביאל נפתחת משימה אחת (עם מה שניסו לרשום) — בלי לגעת בקובץ
function fileGapTask_(name, what) { try { const sh = taskSheet_(), n = sh.getLastRow(); if (n > 1 && sh.getRange(2, 1, n - 1, 8).getValues().some(r => String(r[2]) === name && String(r[6]) === 'file' && String(r[7]) === 'פתוחה')) return;
  let ph = ''; try { ph = String(clientRow(name).get('טלפון') || ''); } catch (e) {}
  sh.appendRow([Utilities.getUuid().slice(0, 8), new Date(), name, 'קובץ המעקב של ' + name.split(' ')[0] + ' צריך עדכון', 'אין בו שורה להיום, אז רישום מהאפליקציה נכשל. ניסה/תה לרשום: ' + what, 'ידנית', 'file', 'פתוחה', '', ph]); } catch (e) {} }
